// HAND-OWNED (quick-log). Not generated by Bubblewrap.
package io.github.palo007.twa.quicklog

import android.content.Context
import androidx.work.BackoffPolicy
import androidx.work.Constraints
import androidx.work.ExistingWorkPolicy
import androidx.work.NetworkType
import androidx.work.OneTimeWorkRequest
import androidx.work.WorkManager
import java.util.concurrent.TimeUnit

/**
 * TWA-26: a reminder edited inside the open TWA is written to Dropbox after the launch sync already ran, and
 * there is no native resume hook. So each launch also arms one delayed follow-up ReminderSyncWorker run.
 *
 * - Own unique name, so the immediate launch sync (REPLACE) and this one never cancel each other.
 * - KEEP: repeated launches within the window keep the one pending request (no pile-up, and no endless
 *   postponement that REPLACE would cause). After it ran, the next launch arms a new one.
 * - TWA-27: never setExpedited. ReminderSyncWorker is a plain Worker without getForegroundInfo (throws on
 *   API < 31 for expedited work) and API 34 would need an FGS type.
 */
object LaunchSync {
    const val WORK_FOLLOW_UP = "questa-reminder-sync-launch-followup"
    const val DELAY_MINUTES = 3L
    @JvmField val POLICY: ExistingWorkPolicy = ExistingWorkPolicy.KEEP

    @JvmStatic
    fun followUpRequest(): OneTimeWorkRequest =
        OneTimeWorkRequest.Builder(ReminderSyncWorker::class.java)
            .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build())
            .setInitialDelay(DELAY_MINUTES, TimeUnit.MINUTES)
            .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
            .build()

    @JvmStatic
    fun enqueueFollowUp(ctx: Context) {
        WorkManager.getInstance(ctx.applicationContext)
            .enqueueUniqueWork(WORK_FOLLOW_UP, POLICY, followUpRequest())
    }
}
